INSERT INTO public."Element" (id, type, title, description, "taskA", "devPromptA", "taskB", "devPromptB", "devPromptC", position, "lessonId") VALUES (6, 'ai2', null, 'Nur KI Feld 2 <pre>ai2</pre>', 'Fix', 'Du bist ein hilfreicher Chatbot für die prompting.schule', 'Dein Text', 'Übersetze den Text in Emoji', null, 240, 2);
