INSERT INTO public."QuizQuestion" (id, question, type, options, correct, "lessonId") VALUES (3, 'Welche Funktionen können genutzt werden?', 'm', '{fill1,fill2,fillMono,fillSide}', '{fill1,fill2,fillMono,fillSide}', 3);
INSERT INTO public."Lesson" (id, "lessonName", "lessonEmoji", "courseId", "URL", active, "starsNeeded", position) VALUES (6, 'Gedächtnis', '🧠', 5, 'gedaechtnis', 1, 1, 30);
INSERT INTO public."Element" (id, type, title, description, "taskA", "devPromptA", "taskB", "devPromptB", "devPromptC", position, "lessonId") VALUES (23, 'text', null, '<h1>Gedächtnis</h1><h2>Was ist Kurzzeitgedächtnis?</h2><p>Das Gedächtnismodul hilft Agenten, frühere Informationen für spätere Antworten zu nutzen. Die einfachste Form ist das Kurzzeitgedächtnis: Frühere Nachrichten werden erneut in den Prompt beziehungsweise in das Kontextfenster geschrieben.</p><p>Ein Sprachmodell hat zwischen zwei einzelnen API-Aufrufen keinen eigenen bleibenden Gesprächszustand. Es kennt nur den Text, der ihm im aktuellen Aufruf mitgegeben wird.</p><h2>Deine Aufgabe</h2><p>Baue in beiden Spalten dieselbe Pizzabestellung auf. Sende die in der Tabelle angeführten Bestellungen in beide Varienten der KI. Du kannst auch eigene Bestellungen hinzufügen</p>', null, null, null, null, null, 10, 6);
INSERT INTO public."Element" (id, type, title, description, "taskA", "devPromptA", "taskB", "devPromptB", "devPromptC", position, "lessonId") VALUES (25, 'aiSideMemory', null, '<h2>Vergleich: ohne und mit Gedächtnis</h2><p>Schicke jede der vier Nachrichten in beide KI-Chats. In Variante A bekommt der Agent jedes Mal nur die neue Nachricht. In Variante B erhält er zusätzlich den bisherigen Gesprächsverlauf.</p><table><thead><tr><th>Nachricht für beide Varianten</th><th>In beide Felder einfügen</th></tr></thead><tbody><tr><td data-prompt-for-both>Ich hätte gerne eine große Pizza.</td><td><button onclick="fillBoth(this)">einfügen</button></td></tr><tr><td data-prompt-for-both>Füge Champignons hinzu.</td><td><button onclick="fillBoth(this)">einfügen</button></td></tr><tr><td data-prompt-for-both>Ich möchte auch Salami.</td><td><button onclick="fillBoth(this)">einfügen</button></td></tr><tr><td data-prompt-for-both>Extra Käse wäre auch gut.</td><td><button onclick="fillBoth(this)">einfügen</button></td></tr><tr><td data-prompt-for-both>Wie lautet meine gesamte Bestellung?</td><td><button onclick="fillBoth(this)">einfügen</button></td></tr></tbody></table><p>Achte besonders auf die letzte Frage: Ohne frühere Informationen ist sie für den Agenten nicht sinnvoll beantwortbar. Mit Gesprächsverlauf kann er die vollständige Bestellung nennen.</p>', 'Variante A: Ohne Kurzzeitgedächtnis', 'Du bist ein knapper Bestellassistent für Pizzabestellungen. Antworte auf Deutsch in höchstens einem kurzen Satz. Nimm jede genannte Bestellung oder Änderung direkt entgegen und bestätige sie. Stelle keine Rückfragen, biete nichts zusätzlich an und füge keine Details hinzu. Bei einer Frage nach der gesamten Bestellung nenne ausschließlich die Informationen aus dem aktuellen Aufruf und erfinde nichts.', 'Variante B: Mit Kurzzeitgedächtnis', null, null, 30, 6);
INSERT INTO public."Element" (id, type, title, description, "taskA", "devPromptA", "taskB", "devPromptB", "devPromptC", position, "lessonId") VALUES (26, 'star', null, '<mark><h2><i class="fas fa-star"></i> Aufgabe: War der Agent ohne Gedächtnis vergesslich?</h2><p>Erkläre, ob sich der Agent in Variante A schlecht erinnern konnte oder ob er die früheren Informationen gar nicht erhalten hat. Beschreibe außerdem, was bei einem Sprachmodell als Kurzzeitgedächtnis dient.</p><p>Löse diese Aufgabe, um einen Stern <i class="fas fa-star"></i> zu erhalten!</p></mark>', 'Deine Erklärung', 'Bewerte, ob die Antwort erklärt, dass der Agent ohne Gedächtnis die früheren Nachrichten nicht erhalten hat und deshalb nicht darauf zurückgreifen konnte. Sie soll außerdem nennen, dass Kurzzeitgedächtnis bei einem Sprachmodell aus erneut mitgesendetem Text oder Gesprächsverlauf im Kontextfenster besteht. Wenn beide Ideen verständlich genannt werden, vergib einen Stern. Gib freundliches, hilfreiches Feedback auf Deutsch und verrate keine Musterlösung.', null, null, null, 40, 6);
INSERT INTO public."Lesson" (id, "lessonName", "lessonEmoji", "courseId", "URL", active, "starsNeeded", position) VALUES (7, 'Planung', '🗓️', 5, 'planung', 1, 1, 40);
INSERT INTO public."QuizQuestion" (id, question, type, options, correct, "lessonId", position) VALUES (4, 'Warum kann ein Werkzeug beim Berechnen deines Alters in Tagen hilfreich sein?', 's', '{"Sprachmodelle können sich bei exakten Rechnungen verrechnen.","Ein Sprachmodell kann ein Geburtsdatum grundsätzlich nicht aus Text erkennen.","Ein Werkzeug ersetzt das Geburtsdatum durch eine Schätzung."}', '{"Sprachmodelle können sich bei exakten Rechnungen verrechnen."}', 4, 10);
INSERT INTO public."QuizQuestion" (id, question, type, options, correct, "lessonId", position) VALUES (5, 'Was bezeichnet der Aktionsraum eines Agenten?', 's', '{"Die Länge seiner letzten Antwort.","Die Möglichkeiten, die ihm zum Handeln zur Verfügung stehen.","Die Anzahl der Nachrichten im Gesprächsverlauf."}', '{"Die Möglichkeiten, die ihm zum Handeln zur Verfügung stehen."}', 4, 20);
INSERT INTO public."QuizQuestion" (id, question, type, options, correct, "lessonId", position) VALUES (6, 'Welche beiden Möglichkeiten gehören in der Lektion zum Aktionsraum des Agenten?', 'm', '{"Die Rechnung mit dem Sprachmodell selbst lösen.","Ein Werkzeug für die Rechnung aufrufen.","Das eigene Sprachmodell neu trainieren.","Das Geburtsdatum der Person verändern."}', '{"Die Rechnung mit dem Sprachmodell selbst lösen.","Ein Werkzeug für die Rechnung aufrufen."}', 4, 30);
INSERT INTO public."QuizQuestion" (id, question, type, options, correct, "lessonId", position) VALUES (7, 'Welche Aufgabe übernimmt das Sprachmodell vor dem Werkzeugaufruf?', 's', '{"Es berechnet die endgültige Tageszahl ohne Werkzeug.","Es speichert das Geburtsdatum dauerhaft im Modell.","Es erkennt das Geburtsdatum aus der Eingabe und bereitet es für den Werkzeugaufruf vor."}', '{"Es erkennt das Geburtsdatum aus der Eingabe und bereitet es für den Werkzeugaufruf vor."}', 4, 40);
INSERT INTO public."QuizQuestion" (id, question, type, options, correct, "lessonId", position) VALUES (8, 'Welche Aufgabe/Aufgaben übernimmt das Werkzeug?', 'm', '{"Es berücksichtigt Schaltjahre bei der Berechnung.","Es liefert eine genaue Tageszahl, die sich überprüfen lässt.","Es wählt ein neues Profil für den Agenten.","Es trainiert das Sprachmodell für zukünftige Rechnungen."}', '{"Es berücksichtigt Schaltjahre bei der Berechnung.","Es liefert eine genaue Tageszahl, die sich überprüfen lässt."}', 4, 50);
INSERT INTO public."QuizQuestion" (id, question, type, options, correct, "lessonId", position) VALUES (9, 'Welche Wirkung hat der Werkzeugaufruf auf den Agenten und seine Antwort?', 's', '{"Er verändert das Sprachmodell dauerhaft, damit es künftig fehlerfrei rechnet.","Er liefert ein Ergebnis für die Antwort, ohne das Sprachmodell selbst zu verändern.","Er macht die Eingabe eines Geburtsdatums überflüssig."}', '{"Er liefert ein Ergebnis für die Antwort, ohne das Sprachmodell selbst zu verändern."}', 4, 60);
INSERT INTO public."QuizQuestion" (id, question, type, options, correct, "lessonId", position) VALUES (10, 'Welche Aufgabe hat das Profil eines Agenten?', 's', '{"Es legt seine Rolle fest und beeinflusst sein Verhalten.","Es speichert automatisch alle früheren Gespräche.","Es berechnet die Dauer jeder Antwort."}', '{"Es legt seine Rolle fest und beeinflusst sein Verhalten."}', 5, 10);
INSERT INTO public."QuizQuestion" (id, question, type, options, correct, "lessonId", position) VALUES (11, 'Was bedeutet Handcrafting eines Profils in dieser Lektion?', 's', '{"Für jede Rolle wird ein neues Sprachmodell trainiert.","Der Agent wählt seine Rolle zufällig aus.","Die gewünschte Rolle wird von Hand direkt in den Prompt geschrieben."}', '{"Die gewünschte Rolle wird von Hand direkt in den Prompt geschrieben."}', 5, 20);
INSERT INTO public."QuizQuestion" (id, question, type, options, correct, "lessonId", position) VALUES (12, 'Warum sollst du allen drei Profilen exakt dieselbe Frage stellen?', 's', '{"Damit alle Antworten garantiert denselben Wortlaut haben.","Damit du den Einfluss des Profils vergleichen kannst, während Frage und Sprachmodell gleich bleiben.","Damit das Sprachmodell die Frage dauerhaft auswendig lernt."}', '{"Damit du den Einfluss des Profils vergleichen kannst, während Frage und Sprachmodell gleich bleiben."}', 5, 30);
INSERT INTO public."QuizQuestion" (id, question, type, options, correct, "lessonId", position) VALUES (13, 'Was kann sich laut Lektion allein durch ein anderes Profil in den Antworten verändern?', 'm', '{"Der Ton und die Formulierungen.","Der Blickwinkel und die besonders betonten Inhalte.","Das verwendete Sprachmodell selbst.","Der Wortlaut der von dir eingegebenen Frage."}', '{"Der Ton und die Formulierungen.","Der Blickwinkel und die besonders betonten Inhalte."}', 5, 40);
INSERT INTO public."QuizQuestion" (id, question, type, options, correct, "lessonId", position) VALUES (14, 'Wozu dient das Gedächtnismodul eines Agenten?', 's', '{"Es macht alle früheren Informationen für spätere Antworten unnötig.","Es hilft dem Agenten, frühere Informationen für spätere Antworten zu nutzen.","Es ersetzt jede neue Nachricht durch eine zufällige frühere Antwort."}', '{"Es hilft dem Agenten, frühere Informationen für spätere Antworten zu nutzen."}', 6, 10);
INSERT INTO public."QuizQuestion" (id, question, type, options, correct, "lessonId", position) VALUES (15, 'Wie funktioniert die einfachste Form des Kurzzeitgedächtnisses in dieser Lektion?', 's', '{"Frühere Nachrichten werden erneut im Prompt beziehungsweise im Kontextfenster mitgegeben.","Nach jedem Gespräch wird das Sprachmodell neu trainiert.","Das Sprachmodell behält von selbst alle Nachrichten zwischen einzelnen Aufrufen."}', '{"Frühere Nachrichten werden erneut im Prompt beziehungsweise im Kontextfenster mitgegeben."}', 6, 20);
INSERT INTO public."QuizQuestion" (id, question, type, options, correct, "lessonId", position) VALUES (16, 'Warum kann das Modell ohne Gedächtnis nicht die gesamte Pizzabestellung nennen?', 's', '{"Das Sprachmodell hat die früheren Nachrichten erhalten, aber schlecht aufgepasst.","Die Frage nach einer gesamten Bestellung ist auch mit Gesprächsverlauf nicht beantwortbar.","Variante A erhält nur die neue Nachricht und bekommt die früheren Bestellangaben nicht mit."}', '{"Variante A erhält nur die neue Nachricht und bekommt die früheren Bestellangaben nicht mit."}', 6, 30);
INSERT INTO public."QuizQuestion" (id, question, type, options, correct, "lessonId", position) VALUES (17, 'Welche Angaben aus den früheren Nachrichten kann das Modell für die gesamte Bestellung nutzen?', 'm', '{"Eine große Pizza.","Champignons.","Extra Käse.","Salami."}', '{"Eine große Pizza.","Champignons.","Extra Käse.","Salami."}', 6, 40);
INSERT INTO public."QuizQuestion" (id, question, type, options, correct, "lessonId", position) VALUES (18, 'Wie kann ein Sprachmodell frühere Nachrichten aus eurem Chat nutzen?', 'm', '{"Die früheren Nachrichten müssen zusammen mit der neuen Nachricht erneut mitgeschickt werden.","Bekommt das Sprachmodell nur die neue Nachricht, kennt es die früheren Nachrichten nicht.","Das Sprachmodell erinnert sich automatisch an alles, was du ihm einmal geschrieben hast.","Damit es frühere Nachrichten nutzen kann, muss das Sprachmodell jedes Mal neu trainiert werden."}', '{"Die früheren Nachrichten müssen zusammen mit der neuen Nachricht erneut mitgeschickt werden.","Bekommt das Sprachmodell nur die neue Nachricht, kennt es die früheren Nachrichten nicht."}', 6, 50);
INSERT INTO public."QuizQuestion" (id, question, type, options, correct, "lessonId", position) VALUES (19, 'Welche Aufgabe übernimmt das Planungsmodul eines Agenten?', 's', '{"Es zerlegt ein Ziel in einfachere Teilaufgaben und ordnet die nötigen Schritte.","Es ersetzt das Ziel durch eine möglichst lange Antwort.","Es führt alle Aufgaben unabhängig von ihrer Reihenfolge gleichzeitig aus."}', '{"Es zerlegt ein Ziel in einfachere Teilaufgaben und ordnet die nötigen Schritte."}', 7, 10);
INSERT INTO public."QuizQuestion" (id, question, type, options, correct, "lessonId", position) VALUES (20, 'Was lässt sich an einem sichtbaren Plan für den Schulweg überprüfen?', 'm', '{"Welche Teilaufgaben nötig sind.","Welche festen Zeiten eingehalten werden müssen.","In welcher Reihenfolge die Schritte aufeinander aufbauen.","Ob das Sprachmodell dadurch dauerhaft neu trainiert wurde."}', '{"Welche Teilaufgaben nötig sind.","Welche festen Zeiten eingehalten werden müssen.","In welcher Reihenfolge die Schritte aufeinander aufbauen."}', 7, 20);
INSERT INTO public."QuizQuestion" (id, question, type, options, correct, "lessonId", position) VALUES (21, 'Nach welcher Zeitangabe müssen sich alle Schritte richten, wenn die Anreise mit dem Bus stattfindet?', 's', '{"Das Frühstück beginnt immer um 8:00 Uhr.","Die Schultasche muss genau um 7:35 Uhr gepackt werden.","Der Bus fährt um 7:35 Uhr ab."}', '{"Der Bus fährt um 7:35 Uhr ab."}', 7, 30);
INSERT INTO public."QuizQuestion" (id, question, type, options, correct, "lessonId", position) VALUES (22, 'Was bedeutet Planung mit Feedback?', 's', '{"Der ursprüngliche Plan bleibt trotz neuer Bedingungen unverändert.","Bei einer geänderten Bedingung werden die betroffenen Schritte und ihre Folgen angepasst.","Bei jeder Änderung müssen auch alle unveränderten Teile vollständig neu erfunden werden."}', '{"Bei einer geänderten Bedingung werden die betroffenen Schritte und ihre Folgen angepasst."}', 7, 40);
INSERT INTO public."QuizQuestion" (id, question, type, options, correct, "lessonId", position) VALUES (23, 'Wegen Regen wechselst du vom Fahrrad zum Bus. Was muss der Agent bei der Plananpassung berücksichtigen?', 'm', '{"Die Gehzeit zur Haltestelle sowie Abfahrtszeit und Fahrtdauer des Busses.","Die Folgen für die Aufstehzeit und den Zeitpunkt zum Verlassen des Hauses.","Das weiterhin geltende Ziel, spätestens um 8:00 Uhr in der Schule zu sein.","Eine neue Frühstücksdauer, obwohl dazu keine Änderung angegeben wurde."}', '{"Die Gehzeit zur Haltestelle sowie Abfahrtszeit und Fahrtdauer des Busses.","Die Folgen für die Aufstehzeit und den Zeitpunkt zum Verlassen des Hauses.","Das weiterhin geltende Ziel, spätestens um 8:00 Uhr in der Schule zu sein."}', 7, 50);
INSERT INTO public."QuizQuestion" (id, question, type, options, correct, "lessonId", position) VALUES (24, 'Welche Informationen gibst du dem Agenten in der Übung zur Plananpassung mit den beiden Prompts?', 's', '{"Nur eine neue Rolle und eine Frage ohne Bezug zum bisherigen Plan.","Nur den ursprünglichen Plan, ohne die gewünschte Änderung zu nennen.","Den ursprünglichen Plan und die gewünschte Änderung."}', '{"Den ursprünglichen Plan und die gewünschte Änderung."}', 7, 60);
INSERT INTO public."Element" (id, type, title, description, "taskA", "devPromptA", "taskB", "devPromptB", "devPromptC", position, "lessonId") VALUES (30, 'text', null, '<h1>Planung</h1><h2>Was ist Planung?</h2><p>Das Planungsmodul hilft einem Agenten, ein Ziel in einfachere, geordnete Teilaufgaben zu zerlegen. Dadurch wird sichtbar, welche Schritte nötig sind und in welcher Reihenfolge sie ausgeführt werden müssen.</p><p>Planung mit Feedback geht noch weiter: Wenn sich eine Bedingung ändert, kann der Agent den betroffenen Teil des Plans anpassen, statt alles von vorne zu beginnen.</p><h2>Deine Aufgabe</h2><p>Vergleiche eine schnelle Antwort ohne sichtbaren Plan mit einer Antwort, die zuerst Teilaufgaben und Zeiten ordnet.</p>', null, null, null, null, null, 10, 7);
INSERT INTO public."Element" (id, type, title, description, "taskA", "devPromptA", "taskB", "devPromptB", "devPromptC", position, "lessonId") VALUES (31, 'aiSide', null, '<h2>Plane deinen Weg zur Schule</h2><p>Probiere die vier Versionen der Reihe nach aus: Sie werden immer anspruchsvoller. Mit jedem Button wird derselbe Prompt in beide KI-Chats eingefügt.</p><table><thead><tr><th>Version</th><th>Nachricht für beide Varianten</th><th>In beide Felder einfügen</th></tr></thead><tbody><tr><td>1: Einfach</td><td data-prompt-for-both>Ich muss um 8:00 Uhr in der Schule sein. Duschen dauert 15 Minuten, Frühstücken 10 Minuten und der Weg zur Schule 20 Minuten. Wann muss ich aufstehen und in welcher Reihenfolge sollte ich die Dinge machen?</td><td><button onclick="fillBoth(this)">einfügen</button></td></tr><tr><td>2: Mit Bus</td><td data-prompt-for-both>Ich muss um 8:00 Uhr in der Schule sein. Frühstücken dauert 10 Minuten und das Packen meiner Schultasche 5 Minuten. Zur Bushaltestelle gehe ich 5 Minuten. Der Bus fährt um 7:35 Uhr ab und braucht 15 Minuten zur Schule. Wann muss ich aufstehen?</td><td><button onclick="fillBoth(this)">einfügen</button></td></tr><tr><td>3: Mit Fahrrad</td><td data-prompt-for-both>Ich muss um 8:00 Uhr in der Schule sein. Frühstücken dauert 10 Minuten und das Packen meiner Schultasche 5 Minuten. Mit dem Fahrrad dauert der direkte Weg zur Schule 10 Minuten. Wann muss ich aufstehen?</td><td><button onclick="fillBoth(this)">einfügen</button></td></tr><tr><td>4: Mit Auto</td><td data-prompt-for-both>Ich muss um 8:00 Uhr in der Schule sein. Frühstücken dauert 10 Minuten und das Packen meiner Schultasche 5 Minuten. Mein Vater kann mich mit dem Auto bringen. Wegen eines Termins muss das Auto um 7:45 Uhr losfahren und die Fahrt dauert 5 Minuten. Wann muss ich aufstehen?</td><td><button onclick="fillBoth(this)">einfügen</button></td></tr></tbody></table><p>Vergleiche bei jeder Version die direkte Antwort mit dem sichtbaren Plan. Achte darauf, welche Teilaufgaben und festen Zeiten klar erkennbar sind.</p>', 'Variante A: Direkte Antwort ohne sichtbaren Plan', 'Antworte auf Deutsch direkt auf die Frage. Gib nur eine kurze Empfehlung mit Aufstehzeit und Abfahrtszeit. Zeige keine getrennten Teilaufgaben, keine Tabelle und keine ausführliche Rechnung.', 'Variante B: Antwort mit sichtbarem Plan', 'Antworte auf Deutsch. Erstelle einen klaren, zeitlich geordneten und überprüfbaren Plan. Trenne Teilaufgaben und feste Zeiten. Rechne alle Abhängigkeiten nachvollziehbar rückwärts. Nenne die Aufstehzeit und den Zeitpunkt zum Verlassen des Hauses.', null, 20, 7);
INSERT INTO public."Element" (id, type, title, description, "taskA", "devPromptA", "taskB", "devPromptB", "devPromptC", position, "lessonId") VALUES (32, 'text', null, '<h2>Was Planung sichtbar macht</h2><p>Je komplexer der Schulweg wird, desto hilfreicher ist es, Teilaufgaben, feste Zeiten und Änderungen getrennt zu betrachten. Ein sichtbarer Plan lässt sich überprüfen und bei neuen Bedingungen gezielt anpassen.</p>', null, null, null, null, null, 30, 7);
INSERT INTO public."Element" (id, type, title, description, "taskA", "devPromptA", "taskB", "devPromptB", "devPromptC", position, "lessonId") VALUES (35, 'ai12', null, '<h2>Plan mit eigenem Feedback anpassen</h2><p>Erstelle in der Übung darüber eine KI-Antwort. Wähle mit einem der beiden Buttons die linke oder rechte Antwort als ursprünglichen Plan für Prompt 1 aus. Wähle für Prompt 2 eine Änderung aus der Tabelle oder beschreibe deine eigene gewünschte Änderung. Sende beide Prompts ab, um den Plan anpassen zu lassen. Übernimm anschließend die andere Antwort und vergleiche die Anpassungen mit derselben Änderung.</p><p><button type="button" onclick="copyPreviousAiSideOutput(this, 0)">Linke KI-Antwort übernehmen</button> <button type="button" onclick="copyPreviousAiSideOutput(this, 1)">Rechte KI-Antwort übernehmen</button></p><h3>Beispiele für Prompt 2: Änderung am Plan</h3><p>Übernimm zuerst einen Plan aus der jeweils angegebenen Version der Übung darüber in Prompt 1. Wähle dann eine Änderung aus der Tabelle oder schreibe eine eigene.</p><table><thead><tr><th>Beispiel</th><th>Änderung am Plan</th><th>In Prompt 2 einfügen</th></tr></thead><tbody><tr><td>1: Regen (Version 3: Mit Fahrrad)</td><td>Es regnet und ich kann nicht mit dem Fahrrad fahren. Stattdessen nehme ich den Bus: Zur Haltestelle gehe ich 5 Minuten. Der Bus fährt um 7:35 Uhr ab und braucht 15 Minuten zur Schule. Passe meinen Plan an. Wann muss ich jetzt aufstehen und das Haus verlassen, um spätestens um 8:00 Uhr in der Schule zu sein?</td><td><button type="button" onclick="fill2(this)">einfügen</button></td></tr><tr><td>2: Bus verpasst (Version 2: Mit Bus)</td><td>Ich habe den Bus um 7:35 Uhr verpasst. Der nächste Bus kommt 10 Minuten später an der Haltestelle an und braucht ebenfalls 15 Minuten zur Schule. Passe meinen Plan an. Um wie viel Uhr komme ich in der Schule an und bin ich noch rechtzeitig um 8:00 Uhr dort?</td><td><button type="button" onclick="fill2(this)">einfügen</button></td></tr><tr><td>3: Sonnenschein</td><td>Die Sonne scheint und ich möchte stattdessen zu Fuß zur Schule gehen. Zu Fuß dauert der Weg 30 Minuten. Passe meinen Plan an. Wann muss ich jetzt aufstehen und losgehen, damit ich weiterhin um 8:00 Uhr in der Schule bin?</td><td><button type="button" onclick="fill2(this)">einfügen</button></td></tr></tbody></table>', 'Prompt 1: Ursprünglicher Plan', 'Antworte auf Deutsch. Die erste Nachricht enthält den ursprünglichen Plan, die zweite Nachricht die gewünschte Änderung. Übernimm die unveränderten Teile des Plans, passe nur die von der Änderung betroffenen Schritte an und erkläre kurz die Folgen. Erstelle eine klare, überprüfbare Zeitleiste.', 'Prompt 2: Änderung am Plan', null, null, 45, 7);
INSERT INTO public."Element" (id, type, title, description, "taskA", "devPromptA", "taskB", "devPromptB", "devPromptC", position, "lessonId") VALUES (34, 'star', null, '<mark><h2><i class="fas fa-star"></i> Aufgabe: Was macht den Plan zuverlässig?</h2><p>Erkläre, warum ein Plan für den Schulweg bei festen Abfahrtszeiten und Änderungen nützlich ist. Beschreibe außerdem, welche Informationen bei Regen oder einem verpassten Bus angepasst werden müssen.</p><p>Löse diese Aufgabe, um einen Stern <i class="fas fa-star"></i> zu erhalten!</p></mark>', 'Deine Erklärung', 'Bewerte, ob die Antwort erklärt, dass ein Plan Teilaufgaben sichtbar macht. Sie soll außerdem nennen, dass bei Änderungen wie Regen oder einem verpassten Bus nur die betroffenen Schritte angepasst werden müssen. Wenn beide Ideen verständlich genannt werden, vergib einen Stern. Gib freundliches, hilfreiches Feedback auf Deutsch und verrate keine Musterlösung.', null, null, null, 50, 7);
